document.addEventListener('DOMContentLoaded',()=>{const trigger=[...document.querySelectorAll('.partners button')][0];if(!trigger)return;trigger.onclick=()=>{const modal=document.createElement('div');modal.className='partner-request';modal.innerHTML='<form><button type="button" class="close">×</button><span class="eyebrow">PARCEIROS LOCAIS</span><h2>Receba opções para sua viagem.</h2><p>Conte o básico e o atendimento poderá indicar passeios, transfer ou guia.</p><label>Seu nome<input required placeholder="Como podemos te chamar?"></label><label>WhatsApp<input required type="tel" placeholder="(24) 00000-0000"></label><label>O que você procura?<select><option>Passeio de barco</option><option>Transfer</option><option>Guia local</option><option>Hospedagem</option><option>Quero combinar opções</option></select></label><button class="send">Preparar solicitação</button><small>Seus dados ficam neste dispositivo até você enviar a solicitação a um parceiro.</small></form>';document.body.appendChild(modal);modal.querySelector('.close').onclick=()=>modal.remove();modal.querySelector('form').onsubmit=e=>{e.preventDefault();localStorage.setItem('angra-partner-request','ready');modal.querySelector('form').innerHTML='<h2>Pedido preparado.</h2><p>Na próxima versão, esta solicitação será direcionada para parceiros disponíveis conforme as datas da viagem.</p><button type="button" class="close">Fechar</button>';modal.querySelector('.close').onclick=()=>modal.remove()};const s=document.createElement('style');s.textContent='.partner-request{position:fixed;inset:0;z-index:40;background:rgba(20,43,58,.7);display:grid;place-items:center;padding:20px}.partner-request form{position:relative;width:100%;max-width:430px;background:#f7f4ec;border-radius:24px;padding:25px}.partner-request h2{font-size:31px;letter-spacing:-.05em;margin:8px 0}.partner-request p{color:#66808b;line-height:1.45}.partner-request label{display:block;font-size:12px;font-weight:700;margin:14px 0}.partner-request input,.partner-request select{display:block;width:100%;box-sizing:border-box;margin-top:6px;padding:12px;border:1px solid #c9ddd8;border-radius:10px;background:#fff}.partner-request .close{position:absolute;right:14px;top:12px;border:0;background:#fff;border-radius:50%;font-size:22px;width:34px;height:34px;cursor:pointer}.partner-request .send{width:100%;border:0;border-radius:11px;background:#f26b4f;color:#fff;padding:13px;font-weight:700;cursor:pointer}.partner-request small{display:block;margin-top:10px;font-size:10px;color:#66808b}';document.head.appendChild(s)}});
